import path from 'path';

import {
  DEFAULT_AI_FUNCTIONS,
  DEFAULT_AI_LIBRARIES
} from './constants.js';

const uniqPush = (store, key, value) => {
  const list = store[key] || (store[key] = []);
  if (!list.includes(value)) {
    list.push(value);
  }
};

const JS_EXTENSIONS = ['.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs', '.mts', '.cts'];
const PYTHON_EXTENSIONS = ['.py'];
const NOTEBOOK_EXTENSIONS = ['.ipynb'];
const R_EXTENSIONS = ['.r', '.rmd'];
const JVM_EXTENSIONS = ['.java', '.scala'];

const JS_SYNTAX = { lineComment: '//', blockComment: ['/*', '*/'], quotes: '\'"`' };
const PYTHON_SYNTAX = { lineComment: '#', quotes: '\'"', tripleQuotes: true };
const R_SYNTAX = { lineComment: '#', quotes: '\'"`' };
const JVM_SYNTAX = { lineComment: '//', blockComment: ['/*', '*/'], quotes: '\'"' };

const blank = (text) => text.replace(/[^\n]/g, ' ');

/**
 * Replace comments (and Python docstrings) with whitespace so commented-out imports are ignored.
 * String literals are kept, so a comment marker inside a string (e.g. a URL) is left alone.
 * Newlines are preserved to keep line-based parsing intact.
 */
const maskComments = (source, { lineComment, blockComment, quotes, tripleQuotes = false }) => {
  let out = '';
  let i = 0;
  while (i < source.length) {
    if (source.startsWith(lineComment, i)) {
      const end = source.indexOf('\n', i);
      const stop = end === -1 ? source.length : end;
      out += blank(source.slice(i, stop));
      i = stop;
      continue;
    }
    if (blockComment && source.startsWith(blockComment[0], i)) {
      const end = source.indexOf(blockComment[1], i + blockComment[0].length);
      const stop = end === -1 ? source.length : end + blockComment[1].length;
      out += blank(source.slice(i, stop));
      i = stop;
      continue;
    }
    const ch = source[i];
    if (!quotes.includes(ch)) {
      out += ch;
      i += 1;
      continue;
    }
    if (tripleQuotes && source.startsWith(ch.repeat(3), i)) {
      const end = source.indexOf(ch.repeat(3), i + 3);
      const stop = end === -1 ? source.length : end + 3;
      out += blank(source.slice(i, stop));
      i = stop;
      continue;
    }
    // Plain string literal: ends at the matching quote; only template literals may span lines.
    let j = i + 1;
    while (j < source.length && source[j] !== ch && !(source[j] === '\n' && ch !== '`')) {
      j += source[j] === '\\' ? 2 : 1;
    }
    const stop = j < source.length && source[j] === ch ? j + 1 : Math.min(j, source.length);
    out += source.slice(i, stop);
    i = stop;
  }
  return out;
};

// Not preceded by an identifier character or a member access (`obj.require(...)`).
const JS_KEYWORD_START = String.raw`(?<![\w$])(?<!(?:^|[^.])\.)`;
const JS_IMPORT_PATTERNS = [
  // import x from 'm' / import type { X } from 'm' / export * from 'm' (bindings may span lines)
  new RegExp(String.raw`${JS_KEYWORD_START}(?:import|export)(?=[\s{*])[\w$*{},\s]*?\bfrom\s*(['"])([^'"\n]+)\1`, 'g'),
  // import 'm'
  new RegExp(String.raw`${JS_KEYWORD_START}import\s*(['"])([^'"\n]+)\1`, 'g'),
  // require('m') / import('m')
  new RegExp(String.raw`${JS_KEYWORD_START}(?:require|import)\s*\(\s*(['"\x60])([^'"\x60\n]+)\1`, 'g')
];

const collectMatches = (patterns, text) => {
  const modules = [];
  for (const pattern of patterns) {
    for (const match of text.matchAll(pattern)) {
      modules.push(match[match.length - 1].trim());
    }
  }
  return modules;
};

const extractJsImports = (source) => collectMatches(JS_IMPORT_PATTERNS, source);

const PYTHON_MODULE = /^[A-Za-z_][\w.]*$/;

const extractPythonImports = (source) => {
  const modules = [];
  const statements = source.replace(/\\\r?\n/g, ' ').split(/[\n;]/);
  for (const raw of statements) {
    const statement = raw.trim();
    const fromMatch = statement.match(/^from\s+([\w.]+)\s+import\b/);
    if (fromMatch) {
      // Relative imports (`from . import x`, `from .models import y`) fail PYTHON_MODULE.
      if (PYTHON_MODULE.test(fromMatch[1])) modules.push(fromMatch[1]);
      continue;
    }
    const importMatch = statement.match(/^import\s+(.+)$/);
    if (!importMatch) continue;
    for (const part of importMatch[1].split(',')) {
      const name = part.trim().split(/\s+as\s+/)[0].trim();
      if (PYTHON_MODULE.test(name)) modules.push(name);
    }
  }
  return modules;
};

const extractNotebookImports = (source) => {
  let notebook;
  try {
    notebook = JSON.parse(source);
  } catch {
    return extractPythonImports(maskComments(source, PYTHON_SYNTAX));
  }
  const code = (notebook.cells || [])
    .filter((cell) => cell.cell_type === 'code')
    .map((cell) => (Array.isArray(cell.source) ? cell.source.join('') : String(cell.source || '')))
    .join('\n');
  return extractPythonImports(maskComments(code, PYTHON_SYNTAX));
};

const R_IMPORT_PATTERN =
  /(?<![\w.])(?:library|require|requireNamespace|loadNamespace)\s*\(\s*(?:package\s*=\s*)?(['"`]?)([A-Za-z][\w.]*)\1/g;

const JVM_IMPORT_PATTERN = /^\s*import\s+(?:static\s+)?([\w.]+)/gm;

// Each language: how to extract module specifiers, and the separator between a module and its sub-modules.
const LANGUAGES = [
  { extensions: JS_EXTENSIONS, separator: '/', extract: (s) => extractJsImports(maskComments(s, JS_SYNTAX)) },
  { extensions: PYTHON_EXTENSIONS, separator: '.', extract: (s) => extractPythonImports(maskComments(s, PYTHON_SYNTAX)) },
  { extensions: NOTEBOOK_EXTENSIONS, separator: '.', extract: extractNotebookImports },
  { extensions: R_EXTENSIONS, separator: null, extract: (s) => collectMatches([R_IMPORT_PATTERN], maskComments(s, R_SYNTAX)) },
  { extensions: JVM_EXTENSIONS, separator: '.', extract: (s) => collectMatches([JVM_IMPORT_PATTERN], maskComments(s, JVM_SYNTAX)) }
];

/**
 * Returns the modules imported by a file as `{ module, separator }` entries.
 * Files with an unrecognised extension are checked for both JS and Python import syntax.
 */
export const extractImports = (content, filePath = '') => {
  const ext = path.extname(filePath).toLowerCase();
  const language = LANGUAGES.find(({ extensions }) => extensions.includes(ext));
  if (language) {
    return language.extract(content).map((module) => ({ module, separator: language.separator }));
  }
  return [
    ...extractJsImports(content).map((module) => ({ module, separator: '/' })),
    ...extractPythonImports(content).map((module) => ({ module, separator: '.' }))
  ];
};

const matchesLibrary = ({ module, separator }, library) => {
  const name = module.toLowerCase();
  const lib = library.toLowerCase();
  return name === lib || (separator !== null && name.startsWith(lib + separator));
};

export const createLibraryDetector = (libraries = DEFAULT_AI_LIBRARIES) => ({
  id: 'libraries',
  analyze({ content, filePath, result }) {
    const imports = extractImports(content, filePath);
    if (!imports.length) return;
    for (const library of libraries) {
      if (imports.some((entry) => matchesLibrary(entry, library))) {
        uniqPush(result.aiLibraryMatches, filePath, library);
        result.markAiFile(filePath);
      }
    }
  }
});

export const createFunctionDetector = (functions = DEFAULT_AI_FUNCTIONS) => ({
  id: 'functions',
  analyze({ content, filePath, result }) {
    for (const func of functions) {
      const regex = new RegExp(`[\\s\\.\\(]${func}\\s*\\(`, 'g');
      if (regex.test(content)) {
        uniqPush(result.aiFunctionMatches, filePath, func);
        result.markAiFile(filePath);
      }
    }
  }
});

export const DEFAULT_DETECTORS = [
  createLibraryDetector(),
  createFunctionDetector()
];

