import { extractImports } from './src/scanners/detectors.js';

const cases = {
  'ws.js': 'import' + ' '.repeat(200000),
  'idents.ts': 'import ' + 'a, '.repeat(100000),
  'exports.js': 'export {\n' + '  x,\n'.repeat(100000),
  'strings.js': "'".repeat(200000),
  'comments.py': '#'.repeat(200000) + '\nimport openai',
  'big.ts': "import OpenAI from 'openai';\nconst x = 1 / 2; // ok\n".repeat(50000),
  'regex.js': "const r = /'/g; import OpenAI from 'openai';\nimport A from '@anthropic-ai/sdk';",
  'bad.ipynb': '{ not json\nimport openai'
};

for (const [name, content] of Object.entries(cases)) {
  const start = performance.now();
  const imports = extractImports(content, name);
  const ms = (performance.now() - start).toFixed(1);
  console.log(name, `${ms}ms`, JSON.stringify([...new Set(imports.map((i) => i.module))]));
}

